        int b = sc.nextInt();
        int l = sc.nextInt();
        int r = sc.nextInt();

        System.out.println(getResult(a, b, l, r));
    }

    static int getResult(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b))
            return (a <= b) ? a + 1 : (2 * a - b);

        int[] patternArr = new int[3 * (a + b) + 1];
        int lastVal = 0;

        for (int i = 1; i <= a; i++) {
            patternArr[i] = i;
            lastVal = i;
        }

        for (int i = a + 1; i <= a + b; i++) {
            patternArr[i] = lastVal;
        }

        for (int i = a + b + 1; i <= a + b + a; i++) {
            int count = 1;
            while (containsInRange(patternArr, count, a + b - a + 1, i - 1))
                count++;
            patternArr[i] = count;
            lastVal = patternArr[i];
        }

        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            patternArr[i] = lastVal;
        }

        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            patternArr[i] = patternArr[i - (a + b)];
        }

        int[] coverageArray = new int[25];
        int startIdx = l % (a + b);
