        int endIdx = r - l + startIdx;
        if (endIdx < startIdx) endIdx += a + b;

        for (int i = startIdx; i <= endIdx; i++) {
            coverageArray[patternArr[i]] = 1;
        }

        int countCoverage = 0;
        for (int i = 1; i <= 24; i++)
            countCoverage += coverageArray[i];

        return countCoverage;
    }

    static boolean containsInRange(int[] arr, int val, int start, int end) {
        for (int i = start; i <= end; i++) {
            if (arr[i] == val)
                return true;
        }
        return false;
    }
