def getResult(a, b, l, r):
    if (r - l + 1) > 2 * (a + b):
        return a if a <= b else (2 * a - b)

    patternArr = [0] * (3 * (a + b) + 1)
    lastVal = 0

    for i in range(1, a + 1):
        patternArr[i] = i
        lastVal = i

    for i in range(a + 1, a + b + 1):
        patternArr[i] = lastVal

    def containsInRange(arr, val, start, end):
        for i in range(start, end + 1):
            if arr[i] == val:
                return True
        return False

    for i in range(a + b + 1, a + b + a + 1):
        count = 1
        while containsInRange(patternArr, count, a + b - a + 1, i - 1):
            count += 1
        patternArr[i] = count
        lastVal = patternArr[i]

    for i in range(a + b + a + 1, a + b + a + b + 1):
        patternArr[i] = lastVal

    for i in range(2 * (a + b) + 1, 3 * (a + b) + 1):
        patternArr[i] = patternArr[i - (a + b)]

    coverageArray = [0] * 25
    startIdx = l % (a + b)
    if startIdx == 0:
        startIdx += a + b
    endIdx = r - l + startIdx
    if endIdx < startIdx:
        endIdx += a + b

    for i in range(startIdx, endIdx + 1):
        coverageArray[patternArr[i]] = 1

    countCoverage = sum(coverageArray[1:25])
    return countCoverage

